async function broadcast(message) {
  if (!js) await connect();
  const data = codec.encode(JSON.stringify(message));
  await js.publish('broadcast.all', data);
}

async function subscribe(channel, handler, consumerGroup = null) {
  if (!js) await connect();

  const opts = consumerOpts();
  opts.durable(consumerGroup || `consumer-${channel.replace(/[.>*]/g, '-')}`);

async function publish(channel, message) {
  if (!js) await connect();
  const data = codec.encode(JSON.stringify(message));
  await js.publish(channel, data);
}

async function setMessage(messageId, message) {
  const data = typeof message === 'string' ? message : JSON.stringify(message);
  await redisClient.set(`msg:${messageId}`, data, 'EX', 86400);

async function checkNatsHealth() {
  try {
    // Try a simple publish/subscribe round-trip
    await nats.publish('health.ping', { ts: Date.now() });
    return 'ok';
  } catch {

// Emit events for models that went offline
for (const [id] of offline) {
  if (oldList.includes(id)) {
    emitter.emit('modelOffline', id);
  }
}

